static inline int nfkc_in_vocab(unsigned cp) { return cp < 0x10000 ? !(nfkc_dropbits[cp >> 3] & (1u << (cp & 7))) : 0; }
/* binary-search the table; returns 1 and fills off/len when found */
static int nfkc_lookup(unsigned cp, unsigned *off, unsigned char *len) {
    int lo = 0, hi = NFKC_TBL_N - 1;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        unsigned c = nfkc_tbl[mid].cp;
        if (c == cp) { *off = nfkc_tbl[mid].off; *len = nfkc_tbl[mid].len; return 1; }
        if (c < cp) lo = mid + 1; else hi = mid - 1;
    }
    return 0;
}

